mapper.select:
SELECT m.id as menu_id, m.parent_id, m.menu_name, m.menu_code, m.menu_type, m.route_name, m.route_path, m.component, m.redirect, m.query_param, m.is_frame, m.is_cache, m.menu_type_flag, m.visible, m.status, m.perms, m.icon, m.order_num, m.is_system, m.remark, m.create_time, m.update_time, m.create_by, m.update_by, m.is_deleted, m.delete_time FROM sys_menu m WHERE m.is_deleted = 0
AND m.menu_name LIKE CONCAT('%', #{menuName}, '%')
AND m.menu_code LIKE CONCAT('%', #{menuCode}, '%')
AND m.menu_type = #{menuType}
AND m.status = #{status}
AND m.parent_id = #{parentId}
ORDER BY m.parent_id ASC, m.order_num ASC
